typedef union hyp_spinlock hyp_spinlock_t;
static inline void hyp_spin_lock(hyp_spinlock_t *lock)
{
	/* EXECUTABLE CN PRECONDITION */

	/* C OWNERSHIP */

	c_add_to_ghost_state((&lock), sizeof(union hyp_spinlock *),
			     get_cn_stack_depth());
	cn_pointer *lock_addr_cn = convert_to_cn_pointer((&lock));

	u32 tmp;
	c_add_to_ghost_state((&tmp), sizeof(unsigned int),
			     get_cn_stack_depth());

	cn_pointer *tmp_addr_cn = convert_to_cn_pointer((&tmp));

	hyp_spinlock_t lockval, newval;
	c_add_to_ghost_state((&lockval), sizeof(union hyp_spinlock),
			     get_cn_stack_depth());

	cn_pointer *lockval_addr_cn = convert_to_cn_pointer((&lockval));

	c_add_to_ghost_state((&newval), sizeof(union hyp_spinlock),
			     get_cn_stack_depth());

	cn_pointer *newval_addr_cn = convert_to_cn_pointer((&newval));

	asm volatile(
		/* Atomically increment the next ticket. */
		".if "
		"1"
		" == 1\n"
		"661:\n\t" /* LL/SC */ "	prfm	pstl1strm, %3\n"
		"1:	ldaxr	%w0, %3\n"
		"	add	%w1, %w0, #(1 << 16)\n"
		"	stxr	%w2, %w1, %3\n"
		"	cbnz	%w2, 1b\n"
		"\n"
		"662:\n"
		".pushsection .altinstructions,\"a\"\n"
		" .word 661b - .\n" /* label           */
		" .word 663f - .\n" /* new instruction */ " .hword "
		"37"
		"\n" /* cpucap          */ " .byte 662b-661b\n" /* source len      */
		" .byte 664f-663f\n" /* replacement len */ ".popsection\n"
		".subsection 1\n"
		"663:\n\t"
		".arch_extension lse\n" /* LSE atomics */ "	mov	%w2, #(1 << 16)\n"
		"	ldadda	%w2, %w0, %3\n"
		".rept	"
		"3"
		"\nnop\n.endr\n"
		"\n"
		"664:\n\t"
		".org	. - (664b-663b) + (662b-661b)\n\t"
		".org	. - (662b-661b) + (664b-663b)\n\t"
		".previous\n"
		".endif\n"
		/* Did we get the lock? */
		"	eor	%w1, %w0, %w0, ror #16\n"
		"	cbz	%w1, 3f\n"
		/*
         * No: spin on the owner. Send a local event to avoid missing an
         * unlock before the exclusive load.
         */
		"	sevl\n"
		"2:	wfe\n"
		"	ldaxrh	%w2, %4\n"
		"	eor	%w1, %w2, %w0, lsr #16\n"
		"	cbnz	%w1, 2b\n"
		/* We got the lock. Critical section starts here. */
		"3:"
		: "=&r"(lockval), "=&r"(newval), "=&r"(tmp), "+Q"(*lock)
		: "Q"(lock->owner)
		: "memory");

	c_remove_from_ghost_state((&tmp), sizeof(unsigned int));

	c_remove_from_ghost_state((&lockval), sizeof(union hyp_spinlock));

	c_remove_from_ghost_state((&newval), sizeof(union hyp_spinlock));

/* EXECUTABLE CN POSTCONDITION */
__cn_epilogue:

	/* C OWNERSHIP */

	c_remove_from_ghost_state((&lock), sizeof(union hyp_spinlock *));
}
static inline void hyp_spin_unlock(hyp_spinlock_t *lock)
{
	/* EXECUTABLE CN PRECONDITION */

	/* C OWNERSHIP */

	c_add_to_ghost_state((&lock), sizeof(union hyp_spinlock *),
			     get_cn_stack_depth());
	cn_pointer *lock_addr_cn = convert_to_cn_pointer((&lock));

	u64 tmp;
	c_add_to_ghost_state((&tmp), sizeof(unsigned long long),
			     get_cn_stack_depth());

	cn_pointer *tmp_addr_cn = convert_to_cn_pointer((&tmp));

	asm volatile(
		".if "
		"1"
		" == 1\n"
		"661:\n\t" /* LL/SC */ "	ldrh	%w1, %0\n"
		"	add	%w1, %w1, #1\n"
		"	stlrh	%w1, %0"
		"\n"
		"662:\n"
		".pushsection .altinstructions,\"a\"\n"
		" .word 661b - .\n" /* label           */
		" .word 663f - .\n" /* new instruction */ " .hword "
		"37"
		"\n" /* cpucap          */ " .byte 662b-661b\n" /* source len      */
		" .byte 664f-663f\n" /* replacement len */ ".popsection\n"
		".subsection 1\n"
		"663:\n\t"
		".arch_extension lse\n" /* LSE atomics */ "	mov	%w1, #1\n"
		"	staddlh	%w1, %0\n"
		".rept	"
		"1"
		"\nnop\n.endr\n"
		"\n"
		"664:\n\t"
		".org	. - (664b-663b) + (662b-661b)\n\t"
		".org	. - (662b-661b) + (664b-663b)\n\t"
		".previous\n"
		".endif\n"
		: "=Q"(lock->owner), "=&r"(tmp)
		:
		: "memory");

	c_remove_from_ghost_state((&tmp), sizeof(unsigned long long));

/* EXECUTABLE CN POSTCONDITION */
__cn_epilogue:

	/* C OWNERSHIP */

	c_remove_from_ghost_state((&lock), sizeof(union hyp_spinlock *));
}
